document.addEventListener("DOMContentLoaded",function(){class GutenaFormsAdmin{constructor(){if("undefined"!==typeof gutenaFormsNotice&&null!==gutenaFormsNotice&&""!==gutenaFormsNotice){setTimeout(()=>{this.dismissAdminNotice()},100)}}isEmpty(data){return"undefined"===typeof data||null===data||""===data}getParents(el,query){let parents=[];while(el.parentNode!==document.body){el.matches(query)&&parents.push(el);el=el.parentNode}return 0<parents.length?parents[0]:false}dismissAdminNotice(){let dismissBtns=document.querySelectorAll(".gutena-forms-admin-notice .notice-dismiss");if(0<dismissBtns.length){let obj=this;for(let i=0;i<dismissBtns.length;i++){dismissBtns[i].addEventListener("click",function(){let notice=obj.getParents(this,".gutena-forms-admin-notice");if(!obj.isEmpty(notice)){let notice_id=notice.getAttribute("id");fetch(gutenaFormsNotice.ajax_url,{method:"POST",credentials:"same-origin",headers:{"Content-Type":"application/x-www-form-urlencoded",Accept:"application/json","X-WP-Nonce":gutenaFormsNotice.nonce},body:new URLSearchParams({action:gutenaFormsNotice.dismiss_notice_action,gfnonce:gutenaFormsNotice.nonce,notice_id:notice_id})}).then(response=>response.json()).then(response=>{notice.remove()}).catch(error=>{console.error("Error:",error)})}})}}}}const newGutenaFormsAdmin=new GutenaFormsAdmin});